const mapGrid=$('#map-grid'), canvas=$('#game-canvas');
let selectedMap=maps[0], selectedMode='teams', selectedLoadout='assault';
for(const [i,map] of maps.entries()) { const card=document.createElement('button'); card.className=`map-card${i===0?' selected':''}`; card.dataset.map=map.id; card.innerHTML=`<span class="map-art" style="--map-art:${map.art}"></span><span class="map-index">0${i+1}</span><span class="map-type">${map.type}</span><span class="map-name">${map.name}</span>`; card.onclick=()=>{document.querySelector('.map-card.selected')?.classList.remove('selected');card.classList.add('selected');selectedMap=map;buildWorld(map);}; mapGrid.append(card); }
