function makeBot(team='red',z=-20){const g=new THREE.Group();enemyGroup.add(g);const isZombie=selectedMode==='zombies';const color=isZombie?0x66765a:team==='blue'?0x497783:0x8d493f;const body=mesh(new THREE.CapsuleGeometry(.36,.7,4,8),mat(color,.86),0,1.05,0,g);body.castShadow=true;const head=mesh(new THREE.SphereGeometry(.25,10,8),mat(isZombie?0x6e8060:0xc2aa8c),0,1.72,0,g);const vest=mesh(new THREE.BoxGeometry(.52,.48,.34),mat(team==='blue'?0x344c50:0x493b36,.7,.15),0,1.1,-.03,g);const pack=mesh(new THREE.BoxGeometry(.34,.48,.2),mat(0x29302a),0,1.12,.24,g);const eyeMat=mat(isZombie?0x80e078:0xd9e4c4,.2,.1,{emissive:isZombie?0x3c942f:0x18251b,emissiveIntensity:1});for(const x of [-.09,.09])mesh(new THREE.SphereGeometry(.035,6,6),eyeMat,x,1.76,-.22,g);const rifle=mesh(new THREE.BoxGeometry(.11,.12,.65),mat(0x202820,.45,.5),.35,1.24,-.08,g);rifle.rotation.x=-.1;g.position.set((Math.random()-.5)*34,0,z);const bot={group:g,team,hp:isZombie?75:100,maxHp:isZombie?75:100,attack:0,walk:Math.random()*5,speed:isZombie?1.45:.9+Math.random()*.55,dead:false,isZombie,body,bar:null};const barGroup=new THREE.Group();g.add(barGroup);barGroup.position.set(0,2.1,0);const back=mesh(new THREE.PlaneGeometry(.72,.08),mat(0x201c1a),0,0,0,barGroup);const fg=mesh(new THREE.PlaneGeometry(.68,.045),mat(isZombie?0x86d35f:team==='blue'?0x58c9de:0xff715d),0,0,.001,barGroup);bot.bar=fg;bots.push(bot);return bot;}
function spawnBots(reset=false){if(reset){for(const b of bots)enemyGroup.remove(b.group);bots=[];}const count=selectedMode==='zombies'?Math.min(4+Math.floor(kills/4),11):selectedMode==='battle'?9:selectedMode==='assassin'?8:10;if(bots.filter(b=>!b.dead).length===0||reset){for(let i=0;i<count;i++){const angle=i/count*Math.PI*2;const team=selectedMode==='teams'&&i%3===0?'blue':'red';makeBot(team,Math.sin(angle)*(23+Math.random()*12));const bot=bots[bots.length-1];bot.group.position.x=Math.cos(angle)*(23+Math.random()*12);}}}
function updateWeapon(){const w=loadouts[selectedLoadout];ammo=w.mag;reserve=w.reserve;$('#weapon-name').textContent=w.name;$('#weapon-class').textContent=w.label;$('#ammo-count').textContent=ammo;$('#reserve-count').textContent=reserve;$('#fire-mode').textContent=selectedLoadout==='scout'?'SEMI':'AUTO';gunMat.color.setHex(w.color);}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');toastTimer=2;$('#toast-live').textContent=message;}
function addFeed(message){const el=document.createElement('div');el.innerHTML=message;$('#feed').prepend(el);setTimeout(()=>el.remove(),3600);}
function updateHud(){ $('#health-value').textContent=Math.max(0,Math.ceil(health));$('#health-bar').style.width=`${Math.max(0,health)}%`;$('#armor-value').textContent=Math.max(0,Math.ceil(armor));$('#ammo-count').textContent=ammo;$('#reserve-count').textContent=reserve;$('#blue-score').textContent=blueScore;$('#red-score').textContent=redScore;$('#inventory-items').innerHTML=`✦ ${lootCollected} RELICS &nbsp; · &nbsp; ${supplies} SUPPLIES`;$('#map-label').textContent=`LOCATION // ${selectedMap.name.toUpperCase()}`;$('#enemy-label').textContent=selectedMode==='zombies'?'THE RISEN':'RAIDERS';}
function startGame(){selectedMap=maps.find(m=>m.id===document.querySelector('.map-card.selected')?.dataset.map)||maps[0];selectedMode=$('#mode-select').value;selectedLoadout=$('#loadout-select').value;$('#objective').textContent=modeInfo[selectedMode].objective;$('#lobby').classList.add('hidden');$('#hud').classList.remove('hidden');$('#end-card').classList.add('hidden');$('#pause-card').classList.add('hidden');health=100;armor=50;blueScore=0;redScore=0;kills=0;roundSeconds=480;elapsed=0;lootCollected=0;supplies=0;gameEnd=false;running=true;paused=false;updateWeapon();buildWorld(selectedMap);spawnBots(true);updateHud();if(matchMedia('(pointer:fine)').matches){canvas.requestPointerLock?.();}else{$('#touch-controls').style.display='block';}}
function leaveGame(){running=false;paused=false;gameEnd=false;document.exitPointerLock?.();$('#hud').classList.add('hidden');$('#lobby').classList.remove('hidden');$('#pause-card').classList.add('hidden');}
function pauseGame(){if(!running||gameEnd)return;paused=true;$('#pause-card').classList.remove('hidden');document.exitPointerLock?.();}
function resumeGame(){if(!running||gameEnd)return;paused=false;$('#pause-card').classList.add('hidden');if(matchMedia('(pointer:fine)').matches)canvas.requestPointerLock?.();}
function finishGame(won){if(gameEnd)return;gameEnd=true;paused=true;document.exitPointerLock?.();$('#end-title').textContent=won?'FIELD CLEARED':'SIGNAL LOST';$('#end-copy').textContent=won?'The line held. The world still needs saving.':'The frontier claimed another. Refit and redeploy.';$('#end-stats').innerHTML=`<span>${kills} ELIMINATIONS</span><span>${lootCollected} RELICS</span><span>${Math.floor(elapsed)}s IN FIELD</span>`;$('#end-card').classList.remove('hidden');}
function damagePlayer(amount){if(armor>0){const absorbed=Math.min(armor,amount*.65);armor-=absorbed;amount-=absorbed;}health-=amount;updateHud();if(health<=0){health=0;finishGame(false);}}
function shoot(){if(!running||paused||gameEnd||shotCooldown>0)return;if(document.pointerLockElement!==canvas&&matchMedia('(pointer:fine)').matches)return;if(ammo<=0){toast('MAGAZINE EMPTY · PRESS R');return;}const w=loadouts[selectedLoadout];ammo--;shotCooldown=w.rate/1000;gun.position.z=.09;gun.rotation.x=.05;updateHud();const origin=camera.position.clone();const direction=new THREE.Vector3();camera.getWorldDirection(direction);raycaster.set(origin,direction);const targets=bots.filter(b=>!b.dead).map(b=>b.body);const hits=raycaster.intersectObjects(targets,false);let hitBot=null;if(hits.length){hitBot=bots.find(b=>b.body===hits[0].object);if(hitBot){hitBot.hp-=w.damage*(selectedLoadout==='scout'?1:1);hitBot.bar.scale.x=Math.max(.01,hitBot.hp/hitBot.maxHp);hitBot.bar.position.x=(1-hitBot.hp/hitBot.maxHp)*-.34;$('#hit-marker').style.opacity='1';setTimeout(()=>$('#hit-marker').style.opacity='0',100);if(hitBot.hp<=0)killBot(hitBot);}}
 // Tracer streak in view creates a quick readable weapon response.
 const flash=new THREE.PointLight(0xffdca0,2,4);flash.position.set(.32,-.24,-1.2);gun.add(flash);setTimeout(()=>gun.remove(flash),45);}
function killBot(bot){if(bot.dead)return;bot.dead=true;bot.group.visible=false;kills++;if(selectedMode==='teams'&&bot.team==='blue')blueScore++;else redScore++;if(selectedMode==='teams'&&bot.team==='red')blueScore++;addFeed(`<b>✦</b> OPERATOR DOWN <span style="color:#a7b3aa">// ${bot.isZombie?'RISEN':'RAIDER'}</span>`);if(Math.random()<.54){spawnLootDrop(bot.group.position.x,bot.group.position.z);}updateHud();const alive=bots.filter(b=>!b.dead).length;if(selectedMode==='zombies'){if(alive===0){toast(`WAVE ${Math.floor(kills/4)+1} CLEARED · RELOADING`);setTimeout(()=>{if(running&&!gameEnd)spawnBots(true);},1600);}}else if((selectedMode==='teams'&&blueScore>=modeInfo.teams.target)||(selectedMode==='battle'&&kills>=modeInfo.battle.target)||(selectedMode==='assassin'&&kills>=modeInfo.assassin.target)){finishGame(true);}else if(alive===0){setTimeout(()=>{if(running&&!gameEnd)spawnBots(true);},1200);}}
function spawnLootDrop(x,z){const g=new THREE.Group();lootGroup.add(g);g.position.set(x,.5,z);const c=mesh(new THREE.BoxGeometry(.7,.5,.5),mat(0x6b7943,.5,.3),0,0,0,g);mesh(new THREE.TorusGeometry(.35,.04,5,4),mat(0xe4f58d,.3,.2,{emissive:0x648326,emissiveIntensity:.3}),0,.4,0,g).rotation.x=Math.PI/2;const l=new THREE.PointLight(0xcdf36b,.8,4);l.position.y=.6;g.add(l);loot.push({group:g,kind:'supply',active:true});}
function reload(){const w=loadouts[selectedLoadout];if(ammo>=w.mag||reserve<=0||!running||paused)return;const need=w.mag-ammo;const take=Math.min(need,reserve);ammo+=take;reserve-=take;updateHud();toast('RELOADED');}
function tryLoot(){if(!running||paused)return;let nearest=null,dist=2.7;for(const item of loot){if(!item.active)continue;const d=camera.position.distanceTo(item.group.position);if(d<dist){dist=d;nearest=item;}}if(!nearest){toast('NO SUPPLIES IN REACH');return;}nearest.active=false;nearest.group.visible=false;if(nearest.kind==='relic'){lootCollected++;armor=Math.min(100,armor+10);toast('ANCIENT RELIC SECURED · +10 ARMOR');}else{supplies++;reserve+=selectedLoadout==='support'?35:25;health=Math.min(100,health+8);toast('FIELD SUPPLIES · +AMMO +VITALS');}updateHud();}

