function tryLoot(){if(!running||paused)return;let nearest=null,dist=2.7;for(const item of loot){if(!item.active)continue;const d=camera.position.distanceTo(item.group.position);if(d<dist){dist=d;nearest=item;}}if(!nearest){toast('NO SUPPLIES IN REACH');return;}nearest.active=false;nearest.group.visible=false;if(nearest.kind==='relic'){lootCollected++;armor=Math.min(100,armor+10);toast('ANCIENT RELIC SECURED · +10 ARMOR');}else{supplies++;reserve+=selectedLoadout==='support'?35:25;health=Math.min(100,health+8);toast('FIELD SUPPLIES · +AMMO +VITALS');}updateHud();}
function updateBots(dt){for(const bot of bots){if(bot.dead)continue;bot.walk+=dt;bot.bar.parent.lookAt(camera.position);const offset=new THREE.Vector3().subVectors(camera.position,bot.group.position);const distance=offset.length();const toward=offset.normalize();bot.group.rotation.y=Math.atan2(toward.x,toward.z);if(bot.team==='blue'&&selectedMode==='teams'){if(distance>9){bot.group.position.addScaledVector(toward,dt*bot.speed*.45);}continue;}if(distance>(bot.isZombie?1.7:10)){bot.group.position.addScaledVector(toward,dt*bot.speed);bot.group.position.x=THREE.MathUtils.clamp(bot.group.position.x,-39,39);bot.group.position.z=THREE.MathUtils.clamp(bot.group.position.z,-39,39);}else if(bot.team==='red'||selectedMode!=='teams'){bot.attack-=dt;if(bot.attack<=0){bot.attack=bot.isZombie?.8:1.55+Math.random()*.7;if(distance<(bot.isZombie?2.3:42)){const chance=bot.isZombie?.42:.28;if(Math.random()<chance)damagePlayer(bot.isZombie?9:7+Math.random()*5);}}}bot.group.position.y=Math.abs(Math.sin(bot.walk*5))*.04;}}
function setPausedByEsc(){if(!running||gameEnd)return;if(paused)resumeGame();else pauseGame();}
function animate(now){requestAnimationFrame(animate);const dt=Math.min(.045,(now-lastFrame)/1000||0);lastFrame=now;const t=clock.getElapsedTime();if(running&&!paused&&!gameEnd){elapsed+=dt;roundSeconds-=dt;shotCooldown=Math.max(0,shotCooldown-dt);if(gun.position.z>0){gun.position.z=Math.max(0,gun.position.z-dt*1.1);gun.rotation.x=Math.max(0,gun.rotation.x-dt*.7);}camera.position.y=1.7+Math.sin(t*9)*.018*(keys.ShiftLeft?.09:1);gun.position.y=gun.userData.baseY+Math.sin(t*9)*.009;
 const forward=(keys.KeyW?1:0)-(keys.KeyS?1:0)+touchForward,side=(keys.KeyD?1:0)-(keys.KeyA?1:0)+touchSide;const speed=(keys.ShiftLeft||keys.ShiftRight?8.3:5.2);if(forward||side){const v=new THREE.Vector3(side,0,-forward).normalize().multiplyScalar(speed*dt).applyAxisAngle(new THREE.Vector3(0,1,0),playerYaw);camera.position.add(v);}camera.position.x=THREE.MathUtils.clamp(camera.position.x,-43,43);camera.position.z=THREE.MathUtils.clamp(camera.position.z,-43,43);
 if(keys.KeyE) {keys.KeyE=false;tryLoot();}if(keys.KeyR){keys.KeyR=false;reload();}if(keys.Space&&selectedMode==='assassin'){keys.Space=false;camera.position.y+=.16;}
 if(firingTouch)shoot();updateBots(dt);for(const l of loot)if(l.active)l.group.rotation.y+=dt*.5;
 if(selectedMode==='battle'){const radius=Math.max(8,40-elapsed*.18);if(Math.hypot(camera.position.x,camera.position.z)>radius)damagePlayer(dt*3);}
 if(roundSeconds<=0){if(selectedMode==='zombies')finishGame(true);else finishGame(blueScore>=redScore||kills>=modeInfo[selectedMode].target);roundSeconds=0;}
 stormTimer+=dt;if(selectedMap.id==='valhalla'&&stormTimer>9){stormTimer=0;sun.intensity=8;setTimeout(()=>sun.intensity=2.6,130);}
 if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('show');}
 $('#timer').textContent=selectedMode==='zombies'?`WAVE ${Math.floor(kills/4)+1}`:`${String(Math.floor(roundSeconds/60)).padStart(2,'0')}:${String(Math.floor(roundSeconds%60)).padStart(2,'0')}`;}
 renderer.render(scene,camera);}
requestAnimationFrame(animate);
function startAim(e){if(!running||paused||gameEnd)return;if(document.pointerLockElement===canvas){shoot();}else if(!matchMedia('(pointer:fine)').matches){shoot();}}
$('#deploy-button').addEventListener('click',startGame);$('#exit-button').addEventListener('click',()=>{if(document.pointerLockElement===canvas)pauseGame();else if(running)pauseGame();});$('#resume-button').addEventListener('click',resumeGame);$('#return-button').addEventListener('click',leaveGame);
canvas.addEventListener('click',()=>{if(running&&!paused&&!gameEnd&&matchMedia('(pointer:fine)').matches&&document.pointerLockElement!==canvas)canvas.requestPointerLock?.();});document.addEventListener('pointerlockchange',()=>{if(!document.pointerLockElement&&running&&!paused&&!gameEnd&&matchMedia('(pointer:fine)').matches)pauseGame();});
document.addEventListener('mousemove',e=>{if(document.pointerLockElement!==canvas||!running||paused)return;playerYaw-=e.movementX*.0022;playerPitch=THREE.MathUtils.clamp(playerPitch-e.movementY*.0019,-1.35,1.35);camera.rotation.order='YXZ';camera.rotation.y=playerYaw;camera.rotation.x=playerPitch;});document.addEventListener('mousedown',e=>{if(e.button===0)startAim(e);});document.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Escape'&&running)setPausedByEsc();if(e.code==='KeyE'&&!e.repeat)tryLoot();if(e.code==='KeyR'&&!e.repeat)reload();});document.addEventListener('keyup',e=>{keys[e.code]=false;});window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));});
// Simple mobile thumb movement pad and accessible fire/loot controls.
const movePad=$('#move-pad');let touchId=null,touchOrigin=null;movePad.addEventListener('pointerdown',e=>{touchId=e.pointerId;touchOrigin={x:e.clientX,y:e.clientY};movePad.setPointerCapture(e.pointerId);});movePad.addEventListener('pointermove',e=>{if(e.pointerId!==touchId||!touchOrigin)return;touchSide=THREE.MathUtils.clamp((e.clientX-touchOrigin.x)/30,-1,1);touchForward=THREE.MathUtils.clamp((touchOrigin.y-e.clientY)/30,-1,1);});movePad.addEventListener('pointerup',e=>{if(e.pointerId===touchId){touchId=null;touchOrigin=null;touchSide=0;touchForward=0;}});$('#fire-touch').addEventListener('pointerdown',e=>{e.preventDefault();firingTouch=true;shoot();});$('#fire-touch').addEventListener('pointerup',()=>firingTouch=false);$('#fire-touch').addEventListener('pointercancel',()=>firingTouch=false);$('#loot-touch').addEventListener('click',tryLoot);
updateWeapon();buildWorld(selectedMap);updateHud();

